export const widgetsDescribeWidget = <ThrowOnError extends boolean = true>(options: Options<WidgetsDescribeWidgetData, ThrowOnError>) => (options.client ?? client).get<WidgetsDescribeWidgetResponses, WidgetsDescribeWidgetErrors, ThrowOnError>({ url: '/api/v1/widgets/{name}', ...options });
